// app/api/public/restock-alert/route.ts — Public Restock Notification Subscription Endpoint
import { NextResponse } from "next/server";
import { checkRateLimit, RATE_LIMIT_TIERS } from "@/src/services/rate-limiter.service";
import { isCloudFirestore } from "@/src/services/firestore-store";
import { getFirestore } from "@/src/db/firestore";
import { getPool } from "@/src/db/pool";

export async function POST(request: Request) {
  try {
    const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "127.0.0.1";
    const ipRateLimit = await checkRateLimit(`restock-alert:ip:${ip}`, RATE_LIMIT_TIERS.public);
    if (!ipRateLimit.allowed) {
      return NextResponse.json(
        { success: false, error: "RATE_LIMITED", message: "Too many attempts. Please try again later." },
        { status: 429 }
      );
    }

    const body = await request.json().catch(() => null);
    if (!body || typeof body !== "object") {
      return NextResponse.json(
        { success: false, error: "INVALID_PAYLOAD", message: "A valid JSON request body is required." },
        { status: 400 }
      );
    }

    const contact = String(body.contact || body.contactHandle || "").trim();
    const productName = String(body.productName || body.product || "").trim();
    const productId = body.productId ? String(body.productId).trim() : (body.slotCode ? String(body.slotCode).trim() : null);
    const variantName = body.variantName ? String(body.variantName).trim() : null;

    let channel = String(body.channel || "").trim().toLowerCase();
    if (!channel) {
      channel = contact.includes("@") && contact.includes(".") && !contact.startsWith("@") ? "email" : "telegram";
    }

    if (!productName) {
      return NextResponse.json(
        { success: false, error: "VALIDATION_ERROR", message: "Product name is required." },
        { status: 400 }
      );
    }

    if (!contact) {
      return NextResponse.json(
        {
          success: false,
          error: "VALIDATION_ERROR",
          message: "Contact handle or email is required to receive restock alerts.",
        },
        { status: 400 }
      );
    }

    const sanitizedPayload = {
      productId: productId || null,
      productName,
      variantName: variantName || null,
      channel,
      contact,
      notes: body.notes ? String(body.notes).trim() : null,
      timestamp: new Date().toISOString(),
    };

    if (isCloudFirestore()) {
      try {
        const db = getFirestore();
        await db.collection("audit_logs").add({
          id: Date.now(),
          action: "RESTOCK_ALERT_SUBSCRIBED",
          entity: `product:${productId || productName}`,
          details: JSON.stringify(sanitizedPayload),
          performed_by: `web:${contact}`,
          created_at: new Date().toISOString(),
        });
      } catch (err: any) {
        console.warn("[Restock Alert POST] Firestore warning:", err?.message || err);
      }
    } else {
      try {
        const pool = getPool();
        await pool.query(
          `INSERT INTO audit_log (actor, action, target, before_summary, after_summary)
           VALUES ($1, $2, $3, $4, $5)`,
          [
            `web:${contact}`,
            "RESTOCK_ALERT_SUBSCRIBED",
            `product:${productId || productName}`,
            null,
            JSON.stringify(sanitizedPayload),
          ]
        );
      } catch (dbErr: any) {
        console.warn("[Restock Alert POST] Postgres audit log warning:", dbErr?.message || dbErr);
      }
    }

    return NextResponse.json({
      success: true,
      message: "Restock alert registered",
    });
  } catch (err: any) {
    console.error("[Restock Alert POST] Uncaught error:", err?.message || err);
    return NextResponse.json(
      { success: false, error: "INTERNAL_ERROR", message: "Failed to register restock alert." },
      { status: 500 }
    );
  }
}
